import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
class ItemTrackerViewTest extends SpringBrowserlessTest {

    @Test
    void shellAndViewShowExpectedHeadingsAndControls() {
        navigate(ItemTrackerView.class);

        assertEquals("Item Tracker", find(H2.class).single().getText());
        assertEquals("Items", find(H1.class).single().getText());

        TextField field = find(TextField.class).single();
        assertEquals("Item", field.getLabel());
        assertEquals("", field.getValue());

        Button add = find(Button.class).withText("Add").single();
        Button clear = find(Button.class).withText("Clear").single();
        assertTrue(add.isEnabled());
        assertTrue(clear.isEnabled());

        assertEquals("Items: 0", test(find(Span.class).single()).getText());
    }

    @Test
    void addingItem_appendsToListAndUpdatesCount() {
        navigate(ItemTrackerView.class);

        TextField field = find(TextField.class).single();
        Button add = find(Button.class).withText("Add").single();

        test(field).setValue("Bread");
        test(add).click();

        UnorderedList list = find(UnorderedList.class).single();
        assertEquals(1, list.getChildren().count());
        ListItem item = find(ListItem.class).single();
        assertEquals("Bread", item.getText());
        assertEquals("", field.getValue());

        Span count = find(Span.class).single();
        assertEquals("Items: 1", test(count).getText());
